3	/// One inspector row (spec §11 CI-9): the horizontal stack `inspectorRow`
4	/// always built — the mark gutter FIRST, with no spacing after it (CI-7) —
5	/// which now tracks the pointer over itself and answers a context menu.
6	///
7	/// The pointer is over the ROW, so the row tells its gutter (`hovered`); the
8	/// gutter decides whether that makes its ◆ a ×. The menu never reads the
9	/// hover: a window that is not key tracks none, and a right-click there must
10	/// offer the same items.
11	///
12	/// A field's or a popup's own right-click keeps its own menu, because neither
13	/// forwards it; the gutter, the label, a slider, a checkbox, the tags and the
14	/// trailing spacer reach this one.
15	final class InspectorRowView: NSStackView {
16	    let gutter: InspectorMarkGutter
17	
18	    init(views: [NSView], gutter: InspectorMarkGutter) {
19	        self.gutter = gutter
20	        super.init(frame: .zero)
21	        for view in views { addArrangedSubview(view) }
22	        orientation = .horizontal
23	        alignment = .centerY
24	        spacing = 6
25	        setCustomSpacing(0, after: gutter)
26	        // As tall as the row and no taller: a fixed height would grow a row
27	        // of bare text (the "No filters" lines) and move everything under it.
28	        gutter.heightAnchor.constraint(equalTo: heightAnchor).isActive = true
29	    }
30	
31	    @available(*, unavailable)
32	    required init?(coder: NSCoder) {
33	        fatalError("InspectorRowView does not support NSCoder")
34	    }
35	
36	    // MARK: Hover
37	
38	    override func updateTrackingAreas() {
39	        super.updateTrackingAreas()
40	        // Only this view's own areas: a tooltip is a tracking area too.
41	        for area in trackingAreas where area.owner === self { removeTrackingArea(area) }
42	        addTrackingArea(
43	            NSTrackingArea(
44	                rect: .zero, options: [.mouseEnteredAndExited, .activeInKeyWindow, .inVisibleRect],
45	                owner: self, userInfo: nil))
46	    }
47	
48	    override func mouseEntered(with event: NSEvent) { setHovered(true) }
49	    override func mouseExited(with event: NSEvent) { setHovered(false) }
50	
51	    func setHovered(_ hovered: Bool) {
52	        gutter.hovered = hovered
53	    }
54	
55	    // MARK: The menu
56	
57	    override func menu(for event: NSEvent) -> NSMenu? {
58	        contextMenu()
59	    }
60	
61	    /// The row's items, in order: "Remove from action N" on a keyed row, "Go
62	    /// to action M" on a ◇ row, then — for a row with a default — "Set end
63	    /// value to default" with an action selected on a row that animates, else
64	    /// "Reset to default", disabled while the row already holds it. Nil when
65	    /// there would be no item.
66	    func contextMenu() -> NSMenu? {
67	        let menu = NSMenu()
68	        menu.autoenablesItems = false
69	        let binding = gutter.binding
70	        if gutter.isKeyed, let number = binding?.selectedActionNumber {
71	            add("Remove from action \(number)", #selector(removeFromAction(_:)), to: menu)
72	        }
73	        if case .other(let number) = gutter.mark {
74	            add("Go to action \(number)", #selector(goToAction(_:)), to: menu)
75	        }
76	        if let rowDefault = gutter.default {
77	            let atEnd = binding?.selectedAction != nil && gutter.animates
78	            let item = add(
79	                atEnd ? "Set end value to default" : "Reset to default",
80	                #selector(resetToDefault(_:)), to: menu)
81	            item.isEnabled = rowDefault.differs()
82	        }
83	        return menu.items.isEmpty ? nil : menu
84	    }
85	
86	    @discardableResult
87	    private func add(_ title: String, _ action: Selector, to menu: NSMenu) -> NSMenuItem {
88	        let item = NSMenuItem(title: title, action: action, keyEquivalent: "")
89	        item.target = self
90	        menu.addItem(item)
91	        return item
92	    }
93	
94	    @objc func removeFromAction(_ sender: Any?) {
95	        gutter.removeFromAction()
96	    }
97	
