99	    @objc func goToAction(_ sender: Any?) {
100	        guard case .other(let number) = gutter.mark, let binding = gutter.binding,
101	              let id = binding.actionID(number: number)
102	        else { return }
103	        binding.selectAction(id)
104	    }
105	
106	    @objc func resetToDefault(_ sender: Any?) {
107	        guard let rowDefault = gutter.default, let binding = gutter.binding else { return }
108	        binding.apply(rowDefault.name, rowDefault.ops())
109	    }
