    /// The chevron's preset menu: each value formatted exactly as the field
    /// shows it at rest, checkmarked on the current value.
    private func showQuickMenu() {
        if field.currentEditor() != nil { finishEditing(commit: true) }
        let menu = NSMenu()
        let current = read()
        for (index, value) in quick.enumerated() {
            let item = NSMenuItem(
                title: String(format: "%.\(decimals)f", value) + unit,
                action: #selector(quickPicked(_:)), keyEquivalent: "")
            item.target = self
            item.tag = index
            item.state = abs(value - current) < 0.0001 ? .on : .off
            menu.addItem(item)
        }
        menu.minimumWidth = bounds.width
        menu.popUp(positioning: nil, at: NSPoint(x: 0, y: bounds.height + 2), in: self)
    }

    @objc private func quickPicked(_ sender: NSMenuItem) {
        guard quick.indices.contains(sender.tag) else { return }
        let value = Swift.min(upper, Swift.max(lower, quick[sender.tag]))
        // Same unchanged-value guard as typed commits: setters that do real
        // work (the selection-morphology fields) must not re-fire on a
        // pick of the value already showing.
        guard abs(value - read()) > 0.0001 else { return }
        write(value)
        onEdit()
        field.stringValue = restText()
    }

    func refresh() {
        isActive = enabled()
        alphaValue = isActive ? 1 : 0.42
        field.isEditable = isActive
        field.isSelectable = isActive
        guard field.currentEditor() == nil else { return }
        field.stringValue = restText()
    }

    // MARK: Editing

    private func restText() -> String {
        bareText() + unit
    }

    private func bareText() -> String {
        String(format: "%.\(decimals)f", read())
    }

    private func beginBareEditing() {
        field.stringValue = bareText()
        if let editor = field.currentEditor() as? NSTextView {
            editor.drawsBackground = false
        }
        field.currentEditor()?.selectAll(nil)
    }

    private func parsedValue(_ text: String) -> Double? {
        var trimmed = text.trimmingCharacters(in: .whitespaces)
        let bareUnit = unit.trimmingCharacters(in: .whitespaces)
        if !bareUnit.isEmpty, trimmed.hasSuffix(bareUnit) {
            trimmed = String(trimmed.dropLast(bareUnit.count))
                .trimmingCharacters(in: .whitespaces)
        }
        return Double(trimmed)
    }

    private func commitCurrentText() {
        guard let value = parsedValue(field.stringValue) else { return }
        let clamped = Swift.min(upper, Swift.max(lower, value))
        // An unchanged value is not an edit: some setters do real work on
        // write (the selection-morphology fields apply their op), so merely
        // focusing a field and tabbing away must not fire them.
        guard abs(clamped - read()) > 0.0001 else { return }
        write(clamped)
        onEdit()
    }

    private func finishEditing(commit: Bool) {
        finishing = true
        if commit { commitCurrentText() }
        window?.makeFirstResponder(window?.contentView)  // #60
        finishing = false
        field.stringValue = restText()
    }

    func control(
        _ control: NSControl, textView: NSTextView, doCommandBy commandSelector: Selector
    ) -> Bool {
        if commandSelector == #selector(NSResponder.insertNewline(_:)) {
            finishEditing(commit: true)
            return true
        }
        if commandSelector == #selector(NSResponder.cancelOperation(_:)) {
            finishEditing(commit: false)
            return true
        }
        return false
    }

    func controlTextDidEndEditing(_ obj: Notification) {
        // Click-away and Tab land here directly; Enter/Escape came through
        // finishEditing and already handled the commit.
        guard !finishing else { return }
        commitCurrentText()
        field.stringValue = restText()
    }
}

